"use strict";
import { createContext, useContext, useState } from "react";
export const VaultContext = createContext(null);
export const VaultContextProvider = ({ children }) => {
  const [activeTab, setActiveTab] = useState("Your position");
  return <VaultContext.Provider value={{ activeTab, setActiveTab }}>{children}</VaultContext.Provider>;
};
export const useVaultContext = () => {
  const context = useContext(VaultContext);
  if (!context) {
    throw new Error("useEarnContext must be used within a EarnContextProvider");
  }
  return context;
};
